        calls.push(args);
        return { status: 1 };
      };

      const available = isAdapterPackageAvailable('@nonexistent/adapter', runner);

      expect(available).toBe(false);
      expect(calls).toEqual([
        ['--no-install', '@nonexistent/adapter', '--help'],
        ['--no-install', '@nonexistent/adapter', '--version'],
      ]);
    });
  });

});

