describe('ralph event translator', () => {
  // Helper to create SessionUpdate objects
  function makeChunk(
    type: 'agent_message_chunk' | 'agent_thought_chunk',
    text: string
  ): SessionUpdate {
    return {
      sessionUpdate: type,
      content: { type: 'text', text },
    } as SessionUpdate;
  }

  describe('agent_message_chunk', () => {
    it('translates streaming content', () => {
