      const cleanEnv = { ...process.env };
      delete cleanEnv.KSPEC_RALPH_SESSION;
      delete cleanEnv.KSPEC_SESSION_ID;

      const { spawnSync: spawnSyncDirect } = await import('node:child_process');
      const result = spawnSyncDirect('node', ['-e', `
