 * Generate multiple unique test ULIDs with the same prefix
 *
 * @param prefix - Prefix for all ULIDs
 * @param count - Number of ULIDs to generate
 * @returns Array of unique valid ULIDs
 *
 * @example
 * const [id1, id2, id3] = testUlids('TASK', 3);
 */
