          const isPlan =
            "derived_tasks" in targetItem || "derived_specs" in targetItem;

          if (!isPlan) {
            warnings.push({
              ref,
              sourceFile,
              sourceUlid: item._ulid,
              field,
              warning: "deprecated_target", // Reuse warning type
              message: `Plan reference "${ref}" points to non-plan item`,
            });
          }
        }
      }
    }
  }

  return { errors, warnings };
}

