        // Delete inbox item unless --keep
        if (!options.keep) {
          await deleteInboxItem(ctx, item._ulid);
          info(`Removed from inbox: ${item._ulid.slice(0, 8)}`);
        }

        await commitIfShadow(
          ctx.shadow,
          "inbox-promote",
          task.slugs[0] || index.shortUlid(task._ulid),
