    )
    .action(async (ref: string, text: string) => {
      try {
        const ctx = await initContext();
        const items = await loadInboxItems(ctx);
        const item = resolveInboxRef(ref, items);
        const itemRef = shortInboxRef(item, items);

        // Append note with separator
