        item.text = item.text + separator + text;

        await saveInboxItem(ctx, item);
        await commitIfShadow(ctx.shadow, "inbox-note", item._ulid.slice(0, 8));

        success(`Added note to inbox item: ${itemRef}`, { item });
      } catch (err) {
