            process.exit(EXIT_CODES.CONFLICT);
          }
        } else {
          // Auto-generated slug: ensure uniqueness across all namespaces
          let counter = 1;
          const baseSlug = planSlug;
          while (!refIndex.isSlugAvailable(planSlug)) {
