        const planRef = shortPlanRef(newPlan, [...plans, newPlan]);

        // AC: @plan-crud ac-1 - auto-commit to shadow branch
        await commitIfShadow(ctx.shadow, "plan-add", newPlan.slugs[0] || newPlan._ulid.slice(0, 8), options.title);

