        // Confirmation required unless --force
        if (!options.force) {
          // AC: @spec-item-delete-children ac-5 - JSON mode requires --force
          if (isJsonMode()) {
            error("Confirmation required. Use --force with --json");
            process.exit(EXIT_CODES.ERROR);
