              }

              await deleteTask(ctx, foundTask);
              await commitIfShadow(
                ctx.shadow,
                "task-delete",
                foundTask.slugs[0] || index.shortUlid(foundTask._ulid),
                foundTask.title,
              );

              return {
                success: true,
                message: `Deleted task: ${taskDisplay}`,
              };
