      async (
        ref: string | undefined,
        options: {
          spec?: string;
          task?: string;
          limit: string;
          oneline?: boolean;
          since?: string;
        },
      ) => {
        try {
          const ctx = await initContext();

          if (!isGitRepo(ctx.rootDir)) {
            error(errors.git.notGitRepo);
            process.exit(EXIT_CODES.ERROR);
          }

