          const dashDashIndex = process.argv.indexOf("--");
          const passthroughArgs =
            dashDashIndex !== -1 ? process.argv.slice(dashDashIndex + 1) : [];

          // Determine what to search for
          const tasks = await loadAllTasks(ctx);
          const items = await loadAllItems(ctx);
          const index = new ReferenceIndex(tasks, items);

          // Build search patterns
          const patterns: string[] = [];

          if (ref) {
            // Resolve the reference to get canonical form
            const result = index.resolve(ref);
            if (!result.ok) {
              error(errors.reference.refNotFound(ref));
              process.exit(EXIT_CODES.NOT_FOUND);
            }

            // Determine if it's a task or spec
            const isTask = tasks.some((t) => t._ulid === result.ulid);
            const refString = normalizeRefInput(ref);

            if (isTask) {
              patterns.push(`Task: ${refString}`);
            } else {
              // For spec items, search for Spec trailer AND Task trailers of linked tasks
              patterns.push(`Spec: ${refString}`);
              // Also find tasks that reference this spec
              const linkedTasks = tasks.filter((t) => t.spec_ref === refString);
              for (const t of linkedTasks) {
                const taskRef = t.slugs[0]
                  ? `@${t.slugs[0]}`
                  : `@${t._ulid.slice(0, 8)}`;
                patterns.push(`Task: ${taskRef}`);
              }
            }
          }

          if (options.spec) {
            patterns.push(`Spec: ${normalizeRefInput(options.spec)}`);
          }

          if (options.task) {
            patterns.push(`Task: ${normalizeRefInput(options.task)}`);
          }

          // AC: @cmd-log list-all-tracked
          // If no patterns specified, list all commits with Task: or Spec: trailers
          if (patterns.length === 0) {
            patterns.push("Task: @");
            patterns.push("Spec: @");
          }

          const limit = parseInt(options.limit, 10);

          // AC: @cmd-log passthrough-args, passthrough-invalid
          // If passthrough args are present, use raw git output
          if (passthroughArgs.length > 0) {
            const rawOutput = searchCommitsRaw(patterns, {
              limit,
              since: options.since,
              cwd: ctx.rootDir,
              passthroughArgs,
            });

            if (!rawOutput.trim()) {
              // AC: @spec-log-empty-repo ac-5
              // Check if repo has no commits vs no matching commits
              if (!hasCommits(ctx.rootDir)) {
                info("No commits in repository yet");
              } else {
                info("No commits found");
              }
            } else {
              console.log(rawOutput);
            }
            return;
          }

          // AC: @spec-log-empty-repo ac-6
          // Check if we should search shadow branch (main has no commits but shadow does)
          const mainHasCommits = hasCommits(ctx.rootDir, false);
          const shadowHasCommits =
            !mainHasCommits && hasCommits(ctx.rootDir, true);
          const searchBranch = shadowHasCommits ? "kspec-meta " : undefined;

          // Search for all patterns and dedupe
          const allCommits: LogCommit[] = [];
          const seenHashes = new Set<string>();

          for (const pattern of patterns) {
            const commits = searchCommits(pattern, {
              limit,
              since: options.since,
              cwd: ctx.rootDir,
              branch: searchBranch,
            });

            for (const commit of commits) {
              if (!seenHashes.has(commit.fullHash)) {
                seenHashes.add(commit.fullHash);
                allCommits.push(commit);
              }
            }
          }

          // Sort by date descending
          allCommits.sort((a, b) => b.date.getTime() - a.date.getTime());

          // Limit results
          const limited = allCommits.slice(0, limit);

          // AC: @spec-log-empty-repo ac-1, ac-2, ac-3, ac-4
          // Handle empty results - differentiate between no commits and no matches
          if (limited.length === 0) {
            if (!hasCommits(ctx.rootDir)) {
              // AC: @spec-log-empty-repo ac-4
              output(
                { commits: [], message: "No commits in repository yet" },
                () => {
                  info("No commits in repository yet");
                },
              );
            } else {
              // AC: @spec-log-empty-repo ac-3 - existing behavior for no matches
              const refStr = ref
                ? ` for ${normalizeRefInput(ref)}`
                : "";
              output({ commits: [] }, () => {
                info(`No commits found${refStr}`);
              });
            }
            return;
          }

          output(limited, () => {
            if (options.oneline) {
              for (const commit of limited) {
                console.log(`${chalk.yellow(commit.hash)} ${commit.subject}`);
              }
            } else {
              for (const commit of limited) {
                console.log(chalk.yellow(`commit ${commit.fullHash}`));
                console.log(`Author: ${commit.author}`);
                console.log(`Date:   ${commit.date.toISOString()}`);
                console.log("");
                console.log(`    ${commit.subject}`);
                console.log("");
              }
            }

            console.log(chalk.gray(`${limited.length} commit(s) found`));
          });
        } catch (err) {
          error(errors.failures.searchCommits, err);
          process.exit(EXIT_CODES.ERROR);
        }
      },
    );
}

