    // Start interactive triage — with EOF on stdin, it will display but not record
    // The key assertion is the count and which items are shown
    const result = kspec(
      "triage start",
      tempDir,
      { stdin: "skip\n" },
    );
    // Should show only 1 item to review (the untriaged one)
