          console.log(`Promoting: "${item.text}"`);
          console.log("");
          title = await prompt("Task title: ");
          if (!title) {
            error(errors.validation.titleRequired);
            process.exit(EXIT_CODES.USAGE_ERROR);
          }
        }

        // Create the task
        const taskInput: TaskInput = {
