        // Sort by created date (newest first)
        plans.sort(
          (a, b) =>
            new Date(b.created_at).getTime() - new Date(a.created_at).getTime(),
        );

        // AC: @plan-crud ac-31 - JSON output
        output(plans, () => {
          if (plans.length === 0) {
            console.log("No plans found");
