  // kspec plan set <ref>
  // AC: @plan-crud ac-3, ac-4
  markMutating(plan.command("set <ref>"))
    .description("Update plan fields")
    .option("--title <title>", "Update title")
    .option("--status <status>", "Update status")
    .option("--slug <slug>", "Add a slug")
