        const plans = await loadPlans(ctx);
        const tasks = await loadAllTasks(ctx);
        const foundPlan = resolvePlanRef(ref, plans);

        // AC: @plan-derive ac-5 - check plan status
        if (foundPlan.status !== "approved" && foundPlan.status !== "active") {
          error(
