          ctx.shadow,
          "plan-derive",
          foundPlan.slugs[0] || foundPlan._ulid.slice(0, 8),
          taskTitle,
        );

        success(`Created task from plan: ${taskRef}`, {
          task: newTask,
          plan: foundPlan,
        });
      } catch (err) {
        error("Failed to derive task from plan", err);
        process.exit(EXIT_CODES.ERROR);
      }
    });
