      "after",
      `
Examples:
  $ kspec plan derive @plan-ref
  $ kspec plan derive @plan-ref --title "Custom title"
  $ kspec plan derive @plan-ref --priority 1`,
    )
    .action(async (ref: string, options) => {
      try {
