  });

  it("should disambiguate displayed refs when triage ULIDs share 8-char prefix", async () => {
    const first = testUlid("ABCDEF", 0);
    const second = testUlid("ABCDEF", 1);
    const triagePath = path.join(tempDir, "spec", "project.triage.yaml");
    await fs.mkdir(path.dirname(triagePath), { recursive: true });

    await fs.writeFile(
      triagePath,
      yamlStringify({
        kynetic_triage: "1.0",
        triage: [
          {
            _ulid: first,
            inbox_ref: testUlid("INBOXA", 0),
            item_snapshot: "First colliding record",
            status: "triaged",
            action: "promote",
            reasoning: "seed",
            decided_by: "@test",
            evidence_refs: [],
            created_at: "2026-01-01T00:00:00.000Z",
          },
          {
