    recordTriage(inboxA, "promote", "seed");
    recordTriage(inboxB, "defer", "seed");

    const existing = kspecJson<
      Array<{
        _ulid: string;
        inbox_ref: string;
        item_snapshot: string;
        status: string;
        action: string;
