    const record = recordTriage(inboxUlid, "defer", "defer it");

    // Act once
    kspec(`triage act @${record._ulid.slice(0, 8)}`, tempDir);

    // Try to act again
    const result = kspec(
      `triage act @${record._ulid.slice(0, 8)}`,
      tempDir,
      { expectFail: true },
    );
